from lib import *
S = SS('e11')
steps = [
    step("LZ77 的输出是字面量,或者“往回看多远、复制多长”。我自己写的实现(哈希链找候选):abracadabra abracadabra → a b r a c a d (7,4) 空格 (12,11),23 字节变成 8 个字面量加 2 个匹配;{\"id\":1,\"id\":2,\"id\":3} → 11 个字面量加 (7,5)、(7,6) 两个匹配;aaaaaaaaaa → 一个字面量 a 加 (1,9)——距离 1、长度 9 的重叠复制,逐字节复制才解得对。三个例子解回原文都一致。products JSON Lines 的开头:先是字面量,到第一个 \"id\":10 附近就出现 (1,5)、(45,7)、(64,3) 这样的匹配。", t=tl(S(1)), done=lidx(S(1), 'b\'aaaaaaaaaa\''), mark=lidx(S(1), 'b\'abracadabra'), b=bars([['abracadabra… 字节', 23, '23'], ['字面量 + 匹配', 10, '8 + 2'], ['aaaaaaaaaa → token 数', 2, '2']], 24, mark=[0], done=[1, 2]), kv=KV([['字面量', '原样输出一个字节'], ['匹配 (d, L)', '往回 d 字节,复制 L 字节'], ['d < L', '重叠复制(游程),逐字节复制']], ['匹配 (d, L)'])),
    step("对 products JSON Lines 的前 128 KiB(131072 字节)做 LZ77(窗口 32 KiB,每个位置最多查 64 个候选,懒匹配):14994 个 token,字面量 5351 个(占输入 4.1%),匹配 9643 个(覆盖输入的 95.9%,平均长度 13.0 字节),解回原文一致。匹配长度:3 字节 1846 个、4 字节 1548、5–8 字节 1604、9–16 字节 2125、17–32 字节 1785、33–258 字节 735;匹配距离:16 以内 42、256 以内 135、4096 以内 3382、32768 以内 6084。绝大多数匹配的距离在 4 KiB 以上——往回看得远才找得到重复。", t=tl(S(2)), done=lidx(S(2), '匹配距离分布'), mark=lidx(S(2), '输入 131072'), b=bars([['距离 ≤16', 42, '42'], ['距离 ≤256', 135, '135'], ['距离 ≤4096', 3382, '3382'], ['距离 ≤32768', 6084, '6084']], 6200, mark=[0, 1], done=[3]), kv=KV([['输入 131072 字节', '14994 个 token'], ['匹配覆盖', '95.9%,平均长 13.0 字节'], ['距离 4 KiB 以上', '6084 个匹配(最多)']], ['距离 4 KiB 以上'])),
    step("往回看多远(窗口大小):我的 LZ77 窗口 256 字节时,匹配只覆盖 30.5% 的输入,估算压缩后 79440 字节;窗口 1024:76.8%,40632;4096:89.9%,36355;16384:96.7%,31497;65536:98.3%,28838;131072:98.4%,28042。真实压缩器,4 MiB 的 pages 数据:zlib 级别 6,windowBits 9(512 字节窗口)1271577、11(2 KiB)1221237、13(8 KiB)1125816、15(32 KiB)919863;zstd 级别 3,windowLog 10(1 KiB)1537347、14(16 KiB)1178377、17(128 KiB)932835、20(1 MiB)831923、22(4 MiB)837102。窗口越大压缩得越小,但窗口大过数据里重复出现的间隔后,收益消失(甚至略有回落)。", t=tl(S(3)), done=lidx(S(3), '    131072'), mark=lidx(S(3), '       256 '), b=bars([['窗口 256:估算字节', 79440, '79440'], ['窗口 4096', 36355, '36355'], ['窗口 65536', 28838, '28838'], ['窗口 131072', 28042, '28042']], 80000, mark=[0], done=[3]), kv=KV([['我的 LZ77,窗口 256 → 131072', '估算 79440 → 28042 字节'], ['zlib windowBits 9 → 15', '1271577 → 919863'], ['zstd windowLog 10 → 20', '1537347 → 831923']], ['zstd windowLog 10 → 20'])),
    step("匹配搜索的努力程度(128 KiB,窗口 32 KiB):贪心,每个位置只看最近 1 个候选,18602 个 token,估算 36153 字节;看 4 个候选 15704 个 token、31825;16 个 14495、30021;64 个 14140、29509;256 个 14016、29308;懒匹配(先看看下一个位置有没有更长的)64 个候选 14994 个 token、估算 28234 字节,256 个候选 28006。zlib 实际:级别 1 34051 字节(0.6 ms)、级别 3 31358(0.8 ms)、级别 6 28441(1.7 ms)、级别 9 28019(2.7 ms)。多花时间找更好的匹配,压缩得更小,每翻几倍的努力换来几个百分点——这就是压缩级别的本质。", t=tl(S(4)), done=lidx(S(4), '      64      是'), mark=lidx(S(4), '       1      否'), b=bars([['贪心 chain 1:估算字节', 36153, '36153'], ['贪心 chain 16', 30021, '30021'], ['贪心 chain 256', 29308, '29308'], ['懒匹配 chain 256', 28006, '28006']], 37000, mark=[0], done=[3]), kv=KV([['候选数 1 → 256(贪心)', '估算 36153 → 29308'], ['懒匹配', '256 候选 28006(用时 0.47 秒)'], ['zlib 级别 1 → 9', '34051 → 28019 字节(0.6 → 2.7 ms)']], ['懒匹配'])),
    step("重叠匹配与匹配长度的上限:全零数据的压缩比随输入长度变化。zlib-9:1 KiB 17 字节(60.2×),16 KiB 39 字节(420.1×),1 MiB 1039 字节(1009.2×),16 MiB 16316(1028.3×),64 MiB 65238(1028.7×);zstd-3 在 1 MiB 50 字节(20971.5×),16 MiB 531(31595.5×),64 MiB 2067(32466.8×);lz4 稳定在 241.6×–242.7×。deflate 的最大匹配长度是 258 字节,压缩比最多约 1000×;zstd 的匹配长度没有这么小的上限,压缩比随输入继续增长。", t=tl(S(5)), done=lidx(S(5), '64.00MiB'), mark=lidx(S(5), '     1.00MiB'), b=bars([['zlib-9 64 MiB', 1028.7, '1028.7×'], ['lz4 64 MiB', 242.7, '242.7×'], ['zstd-3 1 MiB', 20971.5, '20971.5×'], ['zstd-3 64 MiB', 32466.8, '32466.8×']], 33000, mark=[0, 1], done=[3]), kv=KV([['zlib-9', '上限约 1000×(最大匹配 258)'], ['lz4', '约 242×'], ['zstd-3', '64 MiB 零数据 32466.8×']], ['zlib-9'])),
    step("LZ77 的 token 加 Huffman 就是 deflate:用 RFC 1951 的长度码和距离码表(我按记忆写出,自检长度码 3…258 与距离码 1…32768 范围首尾相接没有缺口)估算 token 流的位数。贪心 chain 16:字面量/长度码 67103 位 + 距离码 44287 位 + 额外位 128775 位 = 30021 字节,是 zlib 级别 9 实际 28019 字节的 107%;懒匹配 chain 64:78140 + 35704 + 112028 位 = 28234 字节(不含码表),是实际的 101%。我用 Huffman 对字面量/长度和距离各建一棵树估算的结果,和 zlib 实际只差 1%——deflate 就是这两步。", t=tl(S(6)), done=lidx(S(6), '懒匹配 chain 64'), mark=lidx(S(6), '贪心 chain 16'), b=bars([['贪心 chain 16 估算', 30021, '30021'], ['懒匹配 chain 64 估算', 28234, '28234'], ['zlib 级别 9 实际', 28019, '28019']], 30500, mark=[0], done=[1, 2]), kv=KV([['估算方法', 'token → deflate 长度/距离码表 + Huffman'], ['懒匹配 chain 64', '估算 28234,实际 28019(差 1%)'], ['码表', '长度码 3…258、距离码 1…32768,自检无缺口']], ['估算方法'])),
]
A = mkarte('e11', 11, '压缩原理,LZ77,滑动窗口,哈希链,deflate,重叠匹配,zstd,Python,真实验证,动画演示',
    '自己写 LZ77 并解回原文验证:products 文本 95.9% 的字节被匹配覆盖,匹配距离多在 4 KiB 以上;窗口 256 字节估算 79440、窗口 128 KiB 估算 28042;搜索越努力越小;全零数据 zlib 最多约 1000×、zstd 可到 32466.8×;LZ77 加 Huffman 的估算与 zlib 级别 9 只差 1%。',
    '“压缩比为什么能那么高”的第二层:LZ77 把重复的内容换成“往回看多远、复制多长”。这篇自己写 LZ77,看匹配有多长、离多远、窗口大小和搜索努力怎么换压缩比,并验证 LZ77 加 Huffman 就是 deflate。',
    [('95.9%', '对 128 KiB 的 products 文本做 LZ77,被匹配覆盖的字节比例(字面量只占 4.1%)'), ('79440 对 28042', 'LZ77 窗口 256 字节与 128 KiB 时,估算的压缩后字节数'), ('1028.7× 对 32466.8×', '64 MiB 全零数据:zlib-9 与 zstd-3 的压缩比')],
    [('LZ77 做了什么', '<p>从左到右扫描,每个位置在已经出现过的内容(窗口)里找最长的相同序列:找到就输出(距离,长度),找不到输出字面量。解码只需要按距离往回复制。距离小于长度时就是重叠复制,正好表示“同一个字节重复很多次”。</p>'),
     ('重复从哪来', '<p>products 文本里键名、公共前缀、重复的词不断出现:128 KiB 里 95.9% 的字节被匹配覆盖,平均匹配 13.0 字节,而且多数匹配的距离在 4 KiB 以上。高压缩比的来源就是“前面有相同的内容”。</p>'),
     ('窗口', '<p>往回看得越远,找到的匹配越多、越长。窗口 256 字节时估算 79440 字节,128 KiB 时 28042 字节;真实压缩器 zstd 的窗口从 1 KiB 加到 1 MiB,压缩后从 1537347 字节降到 831923 字节。窗口超过数据里重复出现的间隔后就没有收益了,而窗口越大,压缩和解压要的内存也越大(见第 16 篇)。</p>'),
     ('搜索努力', '<p>每个位置多看几个候选、懒匹配(先看下一个位置有没有更长的),都能找到更好的匹配,代价是时间。zlib 级别 1 到 9 压缩出 34051 到 28019 字节,时间从 0.6 ms 到 2.7 ms。压缩级别本质上就是搜索的努力程度。</p>'),
     ('匹配长度的上限', '<p>deflate 的最大匹配长度是 258 字节,所以哪怕全零数据压缩比也上限约 1000×;zstd 没有这么小的限制,64 MiB 全零能压到 2067 字节(32466.8×)。lz4 的上限更低(约 242×)。</p>'),
     ('LZ77 + Huffman = deflate', '<p>把 LZ77 的 token 按 deflate 的长度/距离码表分类、再用 Huffman 编码,估算出来 28234 字节,zlib 级别 9 实际 28019 字节,只差 1%。gzip 就是这两步;zstd 把第二步换成了更好的熵编码(第 13 篇)。</p>')],
    steps,
    [ENV_E + '。LZ77 是我手写的哈希链实现(3 字节哈希,窗口、候选数、是否懒匹配可调),往回复制逐字节解码并验证了往返;deflate 的长度码和距离码表是我按记忆写出的 RFC 1951 内容,自检了范围连续但没有逐项对照 RFC 原文,估算与 zlib 级别 9 只差 1% 可作旁证;真实压缩器用 zlib 与 zstandard 库;用时是单次测量',
     '没有验证:zstd 的匹配查找算法(哈希表、双哈希、二叉树)具体怎么实现;zstd 的 repeat offset(重复的距离只用很少位表示);LZ4/Snappy 的 token 格式(见第 15 篇);更大的数据集上的窗口曲线;并行压缩把输入切段后损失了多少匹配'],
    'LZ77')
